{"kind": "compare", "icon": "📈", "head": "आर्थिक संवृद्धि बनाम आर्थिक विकास", "left": {"icon": "📊", "t": "संवृद्धि", "d": "उत्पादन और आय बढ़ना<br>सिर्फ़ संख्या — GDP"}, "right": {"icon": "🌱", "t": "विकास", "d": "आय + शिक्षा, स्वास्थ्य, जीवन-स्तर<br>सबकी ज़िंदगी बेहतर"}, "say": "दो शब्दों में फ़र्क़ समझो। आर्थिक संवृद्धि, यानी देश में उत्पादन और आय का बढ़ना, यह सिर्फ़ संख्या है। आर्थिक विकास, इससे बड़ा है। इसमें आय तो बढ़े ही, साथ में लोगों की शिक्षा, स्वास्थ्य, साफ़ पानी, बिजली, और जीवन का स्तर भी बेहतर हो। अगर देश की आय बढ़े, पर सारा पैसा कुछ अमीरों के पास जाए, और ग़रीबों की हालत वैसी ही रहे, तो वह संवृद्धि है, विकास नहीं।"},
{"kind": "content", "icon": "🎯", "head": "अलग लोग, अलग विकास के लक्ष्य", "points": ["भूमिहीन मज़दूर: ज़्यादा दिन काम, ज़्यादा मज़दूरी", "किसान: अच्छा दाम, सिंचाई, बिजली", "शहर की लड़की: बराबर आज़ादी, सुरक्षा", "विस्थापित आदिवासी: अपनी ज़मीन, जंगल पर हक़"], "say": "एक ज़रूरी बात। विकास का मतलब, सबके लिए एक जैसा नहीं होता। भूमिहीन मज़दूर के लिए विकास, यानी साल भर काम, और अच्छी मज़दूरी। किसान के लिए, फ़सल का अच्छा दाम, सिंचाई और बिजली। शहर में पढ़ी-लिखी लड़की के लिए, बराबर आज़ादी, सुरक्षा और नौकरी। और बाँध से उजड़े आदिवासी के लिए, अपनी ज़मीन और जंगल पर हक़। कभी-कभी एक का विकास, दूसरे के लिए नुक़सान भी बन सकता है। इसीलिए विकास, सबकी बात सुनकर होना चाहिए।"},
{"kind": "eq", "icon": "💰", "head": "विकास नापने का पैमाना 1: प्रति व्यक्ति आय", "words": "देश की कुल आय ÷ कुल जनसंख्या", "eq": "प्रति व्यक्ति आय = राष्ट्रीय आय / जनसंख्या", "note": "विश्व बैंक: इसी से देश अमीर (उच्च आय) या ग़रीब (निम्न आय) · भारत: निम्न-मध्यम आय वाला देश", "say": "विकास नापें कैसे? पहला पैमाना, प्रति व्यक्ति आय, यानी देश की कुल आय को, कुल जनसंख्या से भाग दो। इसे औसत आय भी कहते हैं। विश्व बैंक इसी के आधार पर देशों को अमीर, या उच्च आय वाले, और ग़रीब, या निम्न आय वाले देशों में बाँटता है। भारत निम्न-मध्यम आय वाला देश माना जाता है। पर इसमें एक कमी है, औसत से यह पता नहीं चलता, कि आय सबमें बराबर बँटी है या नहीं।"},
{"kind": "table", "head": "औसत की कमी: एक उदाहरण", "eq": "दो गाँव, औसत आय बराबर", "rows": [["", "गाँव क (5 परिवार)", "गाँव ख (5 परिवार)"], ["मासिक आय (₹)", "10000, 10000, 10000, 10000, 10000", "500, 500, 500, 500, 48000"], ["औसत", "₹ 10000", "₹ 10000"], ["कहाँ रहना पसंद?", "सब बराबर, सबका गुज़ारा", "चार परिवार बहुत ग़रीब!"]], "say": "एक उदाहरण से औसत की कमी समझो। दो गाँव, दोनों में पाँच-पाँच परिवार। गाँव क में हर परिवार की मासिक आय दस हज़ार रुपये। गाँव ख में चार परिवारों की पाँच-पाँच सौ, और एक परिवार की अड़तालीस हज़ार। दोनों गाँवों की औसत आय दस हज़ार! पर गाँव ख में चार परिवार बहुत ग़रीब हैं। तो सिर्फ़ औसत आय देखकर, हम सही तस्वीर नहीं जान सकते।"},
{"kind": "eq", "icon": "🏥", "head": "पैमाना 2: मानव विकास सूचकांक (HDI)", "words": "संयुक्त राष्ट्र विकास कार्यक्रम (UNDP) हर साल जारी करता है", "eq": "HDI = आय + स्वास्थ्य (जीवन प्रत्याशा) + शिक्षा (पढ़ाई के वर्ष)", "note": "भारत HDI में अभी काफ़ी पीछे · केरल जैसे राज्य, कम आय पर भी अच्छा HDI", "say": "इसीलिए एक बेहतर पैमाना बना, मानव विकास सूचकांक, या एच डी आई, जिसे संयुक्त राष्ट्र विकास कार्यक्रम हर साल जारी करता है। इसमें तीन चीज़ें देखी जाती हैं। आय, स्वास्थ्य, यानी लोग औसतन कितने साल जीते हैं, जिसे जीवन प्रत्याशा कहते हैं, और शिक्षा, यानी लोगों ने कितने साल पढ़ाई की। भारत इस सूचकांक में दुनिया में काफ़ी पीछे है। पर भारत के अंदर, केरल जैसे राज्य कम आय के बावजूद, अच्छी शिक्षा और स्वास्थ्य सेवाओं से, मानव विकास में बहुत आगे हैं।"},
{"kind": "content", "icon": "🌱", "head": "सतत (टिकाऊ) विकास", "points": ["आज का विकास, कल की पीढ़ी का नुक़सान न करे", "भूजल ज़्यादा निकाला → कल पानी ख़त्म", "पेट्रोल, कोयला सीमित → सौर, पवन ऊर्जा", "पर्यावरण बचाकर विकास"], "say": "एक और ज़रूरी विचार, सतत, या टिकाऊ विकास। यानी ऐसा विकास, जो आज की ज़रूरतें पूरी करे, पर आने वाली पीढ़ियों का नुक़सान न करे। अगर हम आज ज़मीन के नीचे का पानी अंधाधुंध निकालेंगे, तो कल हमारे बच्चों को पानी नहीं मिलेगा। पेट्रोल और कोयला सीमित हैं, इसलिए सूरज और हवा से बिजली बनानी होगी। पर्यावरण बचाकर ही असली विकास संभव है।"},
